import queue

# 输入获取
n = int(input())

tasks = []
for i in range(n):
    tasks.append(input().split())


class Task:
    def __init__(self, taskId, priority, index):
        """
        :param taskId: 任务ID
        :param priority: 任务优先级
        :param index: 任务到达顺序
        """
        self.taskId = taskId
        self.priority = priority
        self.index = index

    def __lt__(self, other):
        if self.priority != other.priority:
            return self.priority > other.priority
        else:
            return self.index < other.index


# 算法入口
def getResult(tasks):
    printer = {}

    taskId = 1
    for i in range(len(tasks)):
        task = tasks[i]

        type = task[0]
        printerId = task[1]

        if type == "IN":
            priority = task[2]
            if printer.get(printerId) is None:
                printer[printerId] = queue.PriorityQueue()
            printer[printerId].put(Task(taskId, int(priority), i))
            taskId += 1
        else:
            if printer.get(printerId) is None or printer[printerId].qsize() == 0:
                print("NULL")
            else:
